<script>
 import {onMount} from 'svelte';import {page} from '$app/stores';import {goto} from '$app/navigation';import {listDomains} from '$lib/api.js';import {locale} from '$lib/i18n.js';import {notify} from '$lib/stores.js';import Button from '$lib/components/Button.svelte';import StatusDot from '$lib/components/StatusDot.svelte';
 let items=[],loading=true,search='',filter='all',error='';$:ru=$locale!=='en';$:projectId=$page.url.searchParams.get('project_id')||'';
 $:filtered=items.filter(x=>{const q=search.trim().toLowerCase();if(q&&!(x.domain+' '+x.site_id+' '+x.device_name).toLowerCase().includes(q))return false;if(filter==='running'&&x.site_status!=='running')return false;if(filter==='stopped'&&x.site_status==='running')return false;return true});
 $:running=items.filter(x=>x.site_status==='running').length;
 async function load(){loading=true;error='';const r=await listDomains(projectId);if(r.ok)items=r.data.domains||[];else{error=r.error||'Could not load domains';notify(error,'error')}loading=false}
 onMount(load);
 function openSite(x){goto('/sites/'+x.device_id+'/'+encodeURIComponent(x.site_id))}
</script>
<svelte:head><title>{ru?'Домены · Yevqo':'Domains · Yevqo'}</title></svelte:head>
<div class="page-header"><div><div class="eyebrow">INFRASTRUCTURE / NETWORKING</div><h1 class="page-title">{ru?'Домены':'Domains'}</h1><p class="page-desc">{ru?'Домены, назначенные приложениям на подключённых Android-устройствах.':'Domains assigned to applications on connected Android devices.'}</p></div><Button on:click={load} disabled={loading}>{ru?'Обновить':'Refresh'}</Button></div>
<div class="metrics"><article><span>{ru?'Всего доменов':'Total domains'}</span><strong>{items.length}</strong></article><article><span>{ru?'Приложения работают':'Applications running'}</span><strong>{running}</strong></article><article><span>{ru?'Маршруты не проверены':'Routing unverified'}</span><strong>{items.filter(x=>x.routing_status!=='verified').length}</strong></article></div>
<div class="toolbar"><input class="input" bind:value={search} placeholder={ru?'Поиск домена, сайта или устройства…':'Search domain, site or device…'}/><select class="input" bind:value={filter}><option value="all">{ru?'Все приложения':'All applications'}</option><option value="running">{ru?'Работают':'Running'}</option><option value="stopped">{ru?'Остановлены / другие':'Stopped / other'}</option></select></div>
{#if loading}<div class="empty">{ru?'Загружаем домены…':'Loading domains…'}</div>{:else if error&&!items.length}<div class="empty"><strong>{ru?'Не удалось загрузить домены':'Could not load domains'}</strong><p>{error}</p><Button on:click={load}>{ru?'Повторить':'Retry'}</Button></div>{:else if !filtered.length}<div class="empty"><strong>{items.length?(ru?'Ничего не найдено':'No matches'):(ru?'Домены ещё не назначены':'No domains assigned yet')}</strong><p>{ru?'Назначь домен в настройках нужного сайта — он появится здесь.':'Assign a domain in the relevant site settings and it will appear here.'}</p><a href="/sites">{ru?'Открыть приложения →':'Open applications →'}</a></div>{:else}
<div class="table-wrap"><table><thead><tr><th>{ru?'ДОМЕН':'DOMAIN'}</th><th>{ru?'ПРИЛОЖЕНИЕ':'APPLICATION'}</th><th>{ru?'УСТРОЙСТВО':'DEVICE'}</th><th>{ru?'ПОРТ':'PORT'}</th><th>{ru?'СТАТУС':'STATUS'}</th><th>{ru?'МАРШРУТ':'ROUTING'}</th><th></th></tr></thead><tbody>{#each filtered as x (x.device_id+':'+x.site_id)}<tr><td><strong>{x.domain}</strong></td><td>{x.site_id}</td><td>{x.device_name||'Android host'}</td><td class="mono">:{x.port}</td><td><StatusDot status={x.site_status}/></td><td><span class="pending">{x.routing_status==='verified'?(ru?'Проверен':'Verified'):(ru?'Не проверен':'Not verified')}</span></td><td><button class="link" on:click={()=>openSite(x)}>{ru?'Настроить →':'Manage →'}</button></td></tr>{/each}</tbody></table></div>{/if}
<div class="note"><strong>{ru?'О доступности домена':'About domain reachability'}</strong><p>{ru?'Сам факт наличия домена не подтверждает его публичную доступность. API пока не предоставляет проверку DNS, TLS и внешнего маршрута, поэтому такие статусы не выдаются за подтверждённые.':'A listed domain is not proof of public reachability. The API does not currently expose DNS, TLS or external routing verification, so those states are not presented as confirmed.'}</p></div>
<style>
.metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-bottom:14px}.metrics article,.note{padding:14px 16px;background:var(--bg-card);border:1px solid var(--border);border-radius:8px}.metrics span{display:block;color:var(--text-muted);font-size:10px}.metrics strong{display:block;margin-top:6px;font-size:23px}.toolbar{display:flex;gap:9px;margin-bottom:12px}.toolbar input{flex:1}.toolbar select{width:auto;min-width:170px}.table-wrap{overflow:auto;border:1px solid var(--border);border-radius:8px;background:var(--bg-card)}table{width:100%;border-collapse:collapse;min-width:720px}th,td{text-align:left;padding:12px 13px;border-bottom:1px solid var(--border);font-size:11px}th{font-size:9px;color:var(--text-muted);letter-spacing:.06em}tbody tr:last-child td{border:0}tbody tr:hover{background:var(--bg-hover)}.mono{font-family:var(--mono)}.pending{font-size:10px;color:var(--warning)}.link{border:0;background:none;color:var(--accent);cursor:pointer}.note{margin-top:14px}.note strong{font-size:11px}.note p{margin-top:4px;color:var(--text-muted);font-size:10px;line-height:1.6}@media(max-width:700px){.metrics{grid-template-columns:1fr}.toolbar{flex-direction:column}.toolbar select{width:100%}}
</style>